using FluentValidation;
namespace YeaFlow.Application.Postings;

/// <summary>
/// Creates a posting intent. <see cref="TransactionId"/> is generated by the client when the user opens the form, so a
/// double click or a browser retry sends the same ID and gets the same intent back.
/// </summary>
public sealed record CreatePostingCommand(
    Guid CompanyId,
    string TransactionId,
    string SapObject,
    string Payload,
    bool SubmitNow);

public sealed class CreatePostingCommandValidator : AbstractValidator<CreatePostingCommand>
{
    public CreatePostingCommandValidator()
    {
        RuleFor(c => c.CompanyId).NotEmpty();
        RuleFor(c => c.TransactionId).NotEmpty().MaximumLength(50).Matches("^[A-Za-z0-9-]+$");
        RuleFor(c => c.SapObject).Must(o => SapObjectPermissions.CreatePermissionFor(o) is not null).WithMessage("Unsupported SAP object.");
        RuleFor(c => c.Payload).NotEmpty().MaximumLength(1_000_000);
    }
}
